// 4-bit wide, 256-to-1 multiplexer
module TopModule(
    input  [1023:0] in,
    input  [7:0] sel,
    output [3:0] out);
    wire [3:0] outs [0:255];
    genvar i;
    generate
        for (i = 0; i < 256; i = i+1) begin : GEN_NAME
            assign outs[i] = in[4*i +: 4];
        end
    endgenerate
    assign out = outs[sel];
endmodule

